import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@supabase/supabase-js";
import { prepareJaspicIdentityCallback } from "../../../../lib/jaspic/oauth-identity-callback";
import { createSupabaseOAuthOnceStore, type JaspicOAuthDbClient } from "../../../../lib/jaspic/oauth-supabase-store";
import { GMAIL_OAUTH_COOKIE_POLICY } from "../../../../lib/jaspic/oauth-session-offline";
import { validateJaspicIdentityTokenResponse } from "../../../../lib/jaspic/oauth-identity-token-validation";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";
function result(success: boolean) {
  const response = NextResponse.redirect(
    "https://emergencyalert.news/jaspic/oauth/result?status=" + (success ? "ok" : "unavailable"),
    { status: 303, headers: { "Cache-Control": "no-store, private", "Referrer-Policy": "no-referrer" } },
  );
  response.cookies.set(GMAIL_OAUTH_COOKIE_POLICY.name, "", {
    httpOnly: true, secure: true, sameSite: "lax", path: "/", maxAge: 0,
  });
  return response;
}

/** Identity-only Google callback. Tokens are not persisted or sent to clients. */
export async function GET(request: NextRequest) {
  if (process.env.JASPIC_OAUTH_START_ENABLED !== "true" ||
      process.env.JASPIC_OAUTH_CALLBACK_ENABLED !== "true") return result(false);
  const cookie = request.cookies.get(GMAIL_OAUTH_COOKIE_POLICY.name)?.value;
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL?.replace(/\/+$/, "");
  const serviceKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
  const clientId = process.env.JASPIC_GOOGLE_WEB_CLIENT_ID;
  const clientSecret = process.env.JASPIC_GOOGLE_WEB_CLIENT_SECRET;
  const cookieKey = process.env.JASPIC_OAUTH_COOKIE_KEY;
  const owner = process.env.JASPIC_ADMIN_USER_ID;
  const expectedEmail = process.env.JASPIC_OAUTH_ADMIN_EMAIL;
  if (!cookie || !url || !/^https:\/\/[a-z0-9-]+\.supabase\.co$/.test(url) ||
      !serviceKey || !clientId || !clientSecret || !cookieKey || !owner || !expectedEmail) return result(false);
  try {
    const db = createClient(url, serviceKey, { auth: { persistSession: false, autoRefreshToken: false } });
    const exchange = await prepareJaspicIdentityCallback({
      callbackUrl: request.url, sealedCookie: cookie, cookieEncryptionKey: cookieKey,
      adminUserId: owner, clientId, clientSecret,
      stateStore: createSupabaseOAuthOnceStore(db as unknown as JaspicOAuthDbClient),
    });
    const response = await fetch(exchange.url, {
      method: exchange.method, headers: exchange.headers, body: exchange.body,
      cache: "no-store", signal: AbortSignal.timeout(10000),
    });
    if (!response.ok) return result(false);
    const token = validateJaspicIdentityTokenResponse(await response.json());
    const profileResponse = await fetch("https://openidconnect.googleapis.com/v1/userinfo", {
      headers: { Authorization: "Bearer " + token.accessToken },
      cache: "no-store", signal: AbortSignal.timeout(10000),
    });
    if (!profileResponse.ok) return result(false);
    const profile: unknown = await profileResponse.json();
    if (!profile || typeof profile !== "object" || Array.isArray(profile)) return result(false);
    const user = profile as Record<string, unknown>;
    if (user.email_verified !== true || typeof user.sub !== "string" ||
        !/^[0-9]{8,32}$/.test(user.sub) ||
        typeof user.email !== "string" ||
        user.email.toLowerCase() !== expectedEmail.toLowerCase()) return result(false);
    return result(true);
  } catch {
    return result(false);
  }
}

"use client";

import { createClient, type SupabaseClient } from "@supabase/supabase-js";
import { useEffect, useMemo, useState } from "react";

function getBrowserClient(): SupabaseClient | null {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL?.replace(/\/+$/, "");
  const key = (process.env.NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY ?? process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY);
  if (!url || !key || !/^https:\/\/[a-z0-9-]+\.supabase\.co$/.test(url)) return null;
  return createClient(url, key, {
    auth: { autoRefreshToken: true, persistSession: true, detectSessionInUrl: true },
  });
}

/**
 * iPhone Safari email OTP login. No OAuth client secret or refresh token is
 * ever exposed to JS. The auth start route must recheck the user on the server.
 */
export default function JaspicOauthLoginClient() {
  const supabase = useMemo(getBrowserClient, []);
  const [email, setEmail] = useState("");
  const [loggedIn, setLoggedIn] = useState(false);
  const [adminStatus, setAdminStatus] = useState<"checking" | "authorized" | "denied">("checking");
  const [message, setMessage] = useState("");
  const [busy, setBusy] = useState(false);
  useEffect(() => {
    if (!supabase) return;
    let active = true;
    void supabase.auth.getUser().then(({data}) => {
      if (active) setLoggedIn(Boolean(data.user));
    }).catch(() => { if (active) setLoggedIn(false); });
    const {data:{subscription}} = supabase.auth.onAuthStateChange((_event,session) => {
      if (active) setLoggedIn(Boolean(session?.user));
    });
    return () => { active = false; subscription.unsubscribe(); };
  }, [supabase]);

  useEffect(() => {
    if (!supabase || !loggedIn) {
      setAdminStatus("checking");
      return;
    }
    let active = true;
    void (async () => {
      try {
        const { data: { session } } = await supabase.auth.getSession();
        if (!session) { if (active) setAdminStatus("denied"); return; }
        const response = await fetch("/jaspic/oauth/status", {
          headers: { authorization: "Bearer " + session.access_token },
          cache: "no-store",
        });
        if (active) setAdminStatus(response.ok ? "authorized" : "denied");
      } catch {
        if (active) setAdminStatus("denied");
      }
    })();
    return () => { active = false; };
  }, [supabase, loggedIn]);

  async function emailLogin() {
    if (!supabase || busy || !email.trim()) return;
    setBusy(true);
    setMessage("");
    try {
      const {error} = await supabase.auth.signInWithOtp({
        email: email.trim(),
        options: { emailRedirectTo: "https://emergencyalert.news/jaspic/oauth", shouldCreateUser: false },
      });
      setMessage(error ? "ログイン用メールを送信できませんでした。設定を確認してください。" :
        "ログイン用メールを送ったよ。メール内のリンクをSafariで開いてね。");
    } catch { setMessage("ログインの準備ができていません。"); }
    finally { setBusy(false); }
  }

  async function beginGoogle() {
    if (!supabase || busy) return;
    setBusy(true);
    setMessage("");
    try {
      const {data:{session}} = await supabase.auth.getSession();
      if (!session) { setMessage("先にメールでログインしてね。"); return; }
      const response = await fetch("/jaspic/oauth/start", {
        method: "POST",
        credentials: "same-origin",
        headers: { authorization: "Bearer " + session.access_token },
        cache: "no-store",
      });
      if (!response.ok) { setMessage("Google認証は現在停止中です。管理者設定を確認してね。"); return; }
      const body: unknown = await response.json();
      if (!body || typeof body !== "object" || !("authorizationUrl" in body) ||
          typeof body.authorizationUrl !== "string") throw new Error("Unavailable");
      const target = new URL(body.authorizationUrl);
      if (target.origin !== "https://accounts.google.com" || target.pathname !== "/o/oauth2/v2/auth") {
        throw new Error("Unavailable");
      }
      window.location.assign(target.href);
    } catch { setMessage("認証開始に失敗しました。"); }
    finally { setBusy(false); }
  }

  return (
    <section>
      {!supabase && <p role="status">ログイン設定はまだ完了していません。</p>}
      {supabase && !loggedIn && <>
        <label htmlFor="jaspic-email">管理者のメールアドレス</label>
        <div style={{display:"flex",gap:8,flexWrap:"wrap",margin:"10px 0"}}>
          <input id="jaspic-email" type="email" value={email}
            onChange={(e)=>setEmail(e.target.value)} autoComplete="email"
            style={{fontSize:16,padding:12,minWidth:230,border:"1px solid #a5bbd0",borderRadius:8}} />
          <button type="button" onClick={()=>void emailLogin()} disabled={busy || !email.trim()}
            style={{fontSize:16,padding:"12px 16px",borderRadius:8}}>ログイン用メールを送る</button>
        </div>
      </>}
      {supabase && loggedIn && <>
        <p>Supabase Authにログイン済みです。管理者本人であることは、次の操作でサーバー側でも確認されます。</p>
        <p role="status" aria-live="polite">{adminStatus === "checking"
          ? "管理者権限を確認しています。"
          : adminStatus === "authorized"
            ? "管理者権限を確認しました。Google認証の開始はサーバー設定によって制御されています。"
            : "管理者権限は未確認です。管理者設定の完了をお待ちください。"}</p>
        <button type="button" onClick={()=>void beginGoogle()} disabled={busy || adminStatus !== "authorized"}
          style={{fontSize:16,padding:"12px 18px",borderRadius:8}}>Google Gmailの認証を開始</button>
        <button type="button" onClick={()=>void supabase.auth.signOut()} disabled={busy}
          style={{fontSize:16,padding:"12px 18px",marginLeft:8,borderRadius:8}}>ログアウト</button>
      </>}
      {message && <p role="status" aria-live="polite">{message}</p>}
    </section>
  );
}

export default async function Page({ searchParams }: { searchParams: Promise<{ status?: string }> }) {
  const params = await searchParams;
  return <main style={{maxWidth:640,margin:"48px auto",padding:24}}>
    <h1>Google本人確認</h1>
    <p role="status">{params.status === "ok"
      ? "本人確認が完了しました。メール送信は有効化されていません。"
      : "本人確認を完了できませんでした。もう一度お試しください。"}</p>
    <a href="/jaspic/oauth">管理者画面に戻る</a>
  </main>;
}

